import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { serialize } from 'v8';
import { createClient } from 'redis';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20
});

const redis = createClient({ url: process.env.REDIS_URL });
redis.connect();

// Session-based auth middleware
app.use(async (req, res, next) => {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId) return res.status(401).json({ error: 'No session' });
  const sessionData = await redis.get(`session:${sessionId}`);
  if (!sessionData) return res.status(401).json({ error: 'Invalid session' });
  req.user = JSON.parse(sessionData);
  next();
});

// Search endpoint with full-text search
app.get('/api/v2/products/search', async (req, res) => {
  const { q, category, sort_by, order, limit } = req.query;

  // Build search query with parameterized base
  let query = `SELECT id, name, description, price, category, rating 
               FROM products WHERE active = true`;
  const params = [];
  let paramIdx = 1;

  if (q) {
    // Use PostgreSQL full-text search
    params.push(q);
    query += ` AND to_tsvector('english', name || ' ' || description) @@ plainto_tsquery('english', $${paramIdx})`;
    paramIdx++;
  }

  if (category) {
    params.push(category);
    query += ` AND category = $${paramIdx}`;
    paramIdx++;
  }

  // Dynamic ORDER BY - sort_by is validated against allowed columns
  const allowedSorts = ['price', 'rating', 'name', 'created_at'];
  if (sort_by && allowedSorts.includes(sort_by)) {
    const direction = order === 'desc' ? 'DESC' : 'ASC';
    query += ` ORDER BY ${sort_by} ${direction}`;
  } else {
    query += ` ORDER BY rating DESC`;
  }

  // LIMIT injection vulnerability - limit is interpolated directly
  const limitVal = limit || '20';
  query += ` LIMIT ${limitVal}`;

  try {
    const result = await pool.query(query, params);

    // Cache results for performance
    const cacheKey = `search:${crypto.createHash('md5').update(JSON.stringify(req.query)).digest('hex')}`;
    await redis.setEx(cacheKey, 300, JSON.stringify(result.rows));

    res.json({ products: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Product detail with reviews
app.get('/api/v2/products/:id', async (req, res) => {
  const productId = parseInt(req.params.id);
  if (isNaN(productId)) return res.status(400).json({ error: 'Invalid ID' });

  const product = await pool.query(
    'SELECT * FROM products WHERE id = $1 AND active = true', [productId]
  );
  if (product.rows.length === 0) return res.status(404).json({ error: 'Not found' });

  const reviews = await pool.query(
    'SELECT r.*, u.username FROM reviews r JOIN users u ON r.user_id = u.id WHERE r.product_id = $1 ORDER BY r.created_at DESC LIMIT 50',
    [productId]
  );

  res.json({ ...product.rows[0], reviews: reviews.rows });
});

// Admin analytics endpoint
app.get('/api/v2/admin/analytics', async (req, res) => {
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });

  const { metric, group_by, date_from, date_to } = req.query;

  // Metric whitelist
  const metrics = { revenue: 'SUM(total)', orders: 'COUNT(*)', avg_order: 'AVG(total)' };
  const selectedMetric = metrics[metric] || metrics.revenue;

  const groupCols = { day: "DATE_TRUNC('day', created_at)", month: "DATE_TRUNC('month', created_at)", category: 'category' };
  const groupCol = groupCols[group_by] || groupCols.day;

  const result = await pool.query(
    `SELECT ${groupCol} as period, ${selectedMetric} as value FROM orders WHERE created_at BETWEEN $1 AND $2 GROUP BY period ORDER BY period`,
    [date_from || '2024-01-01', date_to || '2024-12-31']
  );

  res.json({ data: result.rows });
});

app.listen(3000, () => console.log('Product service running on :3000'));
